const { useState, useRef, useEffect } = React;

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
// Accepts digits, spaces, dashes, parentheses, optional leading +. Requires 7-15 digits.
const PHONE_RE = /^\+?[\d\s\-().]{7,}$/;

function FormField({ id, label, type, value, onChange, onBlur, required, error, helperText, autoComplete, inputMode }) {
  const helperId = `${id}-helper`;
  const errorId = `${id}-error`;
  const describedBy = [helperText ? helperId : null, error ? errorId : null].filter(Boolean).join(" ") || undefined;

  return (
    <div className="form-field">
      <label htmlFor={id}>
        {label}
        {required && <span className="req-mark" aria-hidden="true">*</span>}
      </label>
      <input
        id={id}
        name={id}
        type={type}
        value={value}
        onChange={onChange}
        onBlur={onBlur}
        required={required}
        aria-required={required || undefined}
        aria-invalid={error ? "true" : undefined}
        aria-describedby={describedBy}
        autoComplete={autoComplete}
        inputMode={inputMode}
      />
      {helperText && <div id={helperId} className="helper-text">{helperText}</div>}
      {error && <div id={errorId} className="error-text">{error}</div>}
    </div>
  );
}

function validate(values) {
  const errors = {};
  if (!values.fullName.trim()) {
    errors.fullName = "Please enter your full name.";
  }
  if (!values.email.trim()) {
    errors.email = "Please enter your email address.";
  } else if (!EMAIL_RE.test(values.email.trim())) {
    errors.email = "Enter a valid email address, like name@example.com.";
  }
  if (values.phone.trim() && !PHONE_RE.test(values.phone.trim())) {
    errors.phone = "Enter a valid phone number, e.g. +1 555 123 4567.";
  }
  return errors;
}

function ContactForm() {
  const [values, setValues] = useState({ fullName: "", email: "", phone: "" });
  const [errors, setErrors] = useState({});
  const [touched, setTouched] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [status, setStatus] = useState(null); // { type: 'success'|'error', message }
  const refs = {
    fullName: useRef(null),
    email: useRef(null),
    phone: useRef(null),
  };

  const handleChange = (field) => (e) => {
    const next = { ...values, [field]: e.target.value };
    setValues(next);
    if (submitted || touched[field]) {
      setErrors(validate(next));
    }
  };

  const handleBlur = (field) => () => {
    setTouched((t) => ({ ...t, [field]: true }));
    setErrors(validate(values));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
    const found = validate(values);
    setErrors(found);
    const firstInvalid = ["fullName", "email", "phone"].find((k) => found[k]);
    if (firstInvalid) {
      setStatus({ type: "error", message: "Please fix the errors below and try again." });
      const el = document.getElementById(firstInvalid);
      if (el) el.focus();
      return;
    }
    setStatus({ type: "success", message: "Thanks! Your message has been sent. We'll be in touch soon." });
    setValues({ fullName: "", email: "", phone: "" });
    setTouched({});
    setSubmitted(false);
  };

  return (
    <section className="card" aria-labelledby="form-title">
      <h2 id="form-title">Contact support</h2>
      <p className="lede">Send us a message and a member of our team will get back to you.</p>
      <p className="required-note">
        Fields marked with <span className="req-mark" aria-hidden="true">*</span> are required.
      </p>

      <form onSubmit={handleSubmit} noValidate>
        <FormField
          id="fullName"
          label="Full name"
          type="text"
          value={values.fullName}
          onChange={handleChange("fullName")}
          onBlur={handleBlur("fullName")}
          required
          error={errors.fullName}
          autoComplete="name"
        />
        <FormField
          id="email"
          label="Email address"
          type="email"
          value={values.email}
          onChange={handleChange("email")}
          onBlur={handleBlur("email")}
          required
          error={errors.email}
          autoComplete="email"
          inputMode="email"
        />
        <FormField
          id="phone"
          label="Phone number (optional)"
          type="tel"
          value={values.phone}
          onChange={handleChange("phone")}
          onBlur={handleBlur("phone")}
          error={errors.phone}
          helperText="Include country code if outside the US, e.g. +1 555 123 4567."
          autoComplete="tel"
          inputMode="tel"
        />
        <button type="submit">Send message</button>

        <div role="status" aria-live="polite" aria-atomic="true">
          {status && (
            <div className={`status${status.type === "error" ? " error" : ""}`}>
              {status.message}
            </div>
          )}
        </div>
      </form>
    </section>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<ContactForm />);

